.dashboard-hero::after { content: ''; position: absolute; right: -5rem; bottom: -7rem; width: 18rem; height: 18rem; border: 1px solid rgba(141, 230, 216, .2); border-radius: 999px; box-shadow: 0 0 0 2rem rgba(141,230,216,.03), 0 0 0 4rem rgba(141,230,216,.025); }
